    // Check if there is a byte available in the buffer
    if (buffer.available() > 0) {
        // Return the next byte from the buffer
        return (byte) buffer.read();
    } else {
        // Refill the buffer
        buffer.compact();
        int bytesRead = socket.getInputStream().read(buffer.array());
        if (bytesRead == -1) {
            throw new IOException("No more data available");
        }
        // Allow the buffer to grow if the data exceeds its capacity
        buffer.flip();
        return (byte) buffer.read();
    }
}

