    // Check if the node has a right child
    if (node.right != null) {
        // Find the node's right-most child
        TreeNode<T> rightMostChild = node.right;
        while (rightMostChild.left != null) {
            rightMostChild = rightMostChild.left;
        }

        // Perform the rotation
        node.right = rightMostChild.left;
        rightMostChild.left = node;
        return rightMostChild;
    } else {
        return null;
    }
}

