    if (node == null) {
        return null;
    }

    // Create a new parent node to the right of the current node
    TreeNode<T> newParent = new TreeNode<T>(node.value);
    newParent.left = node.left;
    newParent.right = node.right;
    newParent.height = node.height;

    // Update the child pointers of the current node
    node.left = newParent;
    node.right = node.right.left;
    node.height = Math.max(newParent.height, node.right.height) + 1;

    return newParent;
}

