public static Supplier<String> createStringSupplier(int start) {
    // Create a new HashSet to store the generated strings
    Set<String> strings = new HashSet<>();

    // Generate a new string by appending the next integer to the start value
    // This can lead to collisions and duplicates, so we need to check for them
    // in the hashset
    int next = start;
    while (true) {
        String string = Integer.toString(next);
        if (strings.add(string)) {
            return () -> string;
        }
        next++;
    }
}

