        }
        previous = current;
        current = current.next;
    }

    // Check if the node is found
    if (previous == null) {
        // If the node is not found, return false
        return false;
    }

    // Unlink the node from the list
    previous.next = current.next;
    size--;

    // Return true
    return true;
}

