public static final <V> void reverse(V[] arr, int from, int to) {
    if (from < 0 || from > to || to >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid range indices: from=" + from + ", to=" + to);
    }

    int mid = (from + to) / 2;
    for (int i = from, j = to; i < mid; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

