public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            // Check for escape sequences
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                if (next == 'n') {
                    // newline
                    builder.append('\n');
                    i++;
                } else if (next == 'r') {
                    // carriage return
                    builder.append('\r');
                    i++;
                } else if (next == 't') {
                    // tab
                    builder.append('\t');
                    i++;
                } else if (next == 'b') {
                    // backspace
                    builder.append('\b');
                    i++;
                } else if (next == 'f') {
                    // form feed
                    builder.append('\f');
                    i++;
                } else if (next == '\\') {
                    // backslash
                    builder.append('\\');
                    i++;
                } else if (next == '\'') {
                    // apostrophe
                    builder.append('\'');
                    i++;
                } else if (next == '"') {
                    // double quote
                    builder.append('"');
                    i++;
                }
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

