public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    this.buffer.clear();

    // Read the byte stream into the buffer
    int read;
    while ((read = in.read()) != -1) {
        // Check if the buffer is full
        if (this.buffer.position() == this.buffer.capacity()) {
            // The buffer is full, reset the read pointer to the beginning
            this.buffer.flip();

            // Reallocate the buffer to twice the size
            ByteBuffer newBuffer = ByteBuffer.allocate(this.buffer.capacity() * 2);
            newBuffer.put(this.buffer);
            this.buffer = newBuffer;
        }

        // Add the byte to the buffer
        this.buffer.put((byte) read);
    }

    // Set the limit of the buffer to the number of bytes read
    this.buffer.limit(this.buffer.position());

    // Reset the read pointer to the beginning of the buffer
    this.buffer.flip(); 
}

