@Override
public Action inspect(AtmosphereResource r) {
    // Handle invalid inputs and potential runtime issues
    try {
        if (r == null || !r.isOpen()) {
            return Action.ABORT;
        }

        // Determine the transport type based on the AtmosphereResource
        Transport transport = r.transport();

        // Suspend the AtmosphereResource based on the transport type
        if (transport == Transport.WEBSOCKET) {
            r.suspend(Long.MAX_VALUE);
        } else if (transport == Transport.LONG_POLLING) {
            r.suspend(1000L);
        } else {
            return Action.ABORT;
        }

        return Action.CONTINUE;
    } catch (Exception e) {
        // Handle potential runtime issues
        e.printStackTrace();
        return Action.ABORT;
    }
}

