    if (source == null || candidates == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Iterate over the candidates and check if any of them is present in the source
    for (Object candidate : candidates) {
        if (source.contains(candidate)) {
            return candidate;
        }
    }

    // If no candidate is present in the source, return null
    return null;
}

