public void handleLogEvent(LoggingEvent event) {
    try {
        // get the message to be logged from the LoggingEvent object
        String message = event.getMessage();

        // get the list of connected clients
        Map<String, WebSocket> clients = getConnectedClients();

        // if there are no connected clients, do nothing
        if (clients.isEmpty()) {
            return;
        }

        // loop through the list of clients and send the message to each one
        for (WebSocket client : clients.values()) {
            // send the message to the client
            client.send(message);
        }
    } catch (IOException e) {
        // ignore the exception and continue
    }
}

