public List<SequenceRange> buildSequenceRanges() {
    // Initialize an array to store the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Get the current user's profiles
    List<Profile> profiles = getProfiles();

    // Iterate over the profiles and build a sequence range for each
    for (Profile profile : profiles) {
        // Get the profile's segments
        List<Segment> segments = profile.getSegments();

        // Iterate over the segments and build a sequence range for each
        for (Segment segment : segments) {
            // Get the segment's snapshot
            SegmentSnapshot snapshot = segment.getSnapshot();

            // Get the number of times the snapshot has been seen
            int snapshotCount = snapshot.getSnapshotCount();

            // Create a sequence range for the snapshot
            sequenceRanges.add(new SequenceRange(snapshot.getStart(), snapshot.getEnd(), snapshotCount));
        }
    }

    // Return the sequence ranges
    return sequenceRanges;
}

