    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IOException("Invalid time ranges provided.");
    }
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] splits = line.split(",");
            if (splits.length != 4) {
                throw new IOException("Invalid input line format.");
            }
            long threadId = Long.parseLong(splits[0]);
            long eventTime = Long.parseLong(splits[1]);
            String eventType = splits[2];
            String eventInfo = splits[3];
            if (!eventType.equals("start") && !eventType.equals("end")) {
                throw new IOException("Invalid event type.");
            }
            if (eventType.equals("start")) {
                ProfileAnalyzeTimeRange timeRange = timeRanges.get(0);
                long rangeStart = timeRange.getStartTime();
                long rangeEnd = timeRange.getEndTime();
                if (eventTime >= rangeStart && eventTime <= rangeEnd) {
                    threadSnapshots.add(new ThreadSnapshot(threadId, eventTime, eventType, eventInfo));
                }
            } else if (eventType.equals("end")) {
                ProfileAnalyzeTimeRange timeRange = timeRanges.get(timeRanges.size() - 1);
                long rangeStart = timeRange.getStartTime();
                long rangeEnd = timeRange.getEndTime();
                if (eventTime >= rangeStart && eventTime <= rangeEnd) {
                    threadSnapshots.add(new ThreadSnapshot(threadId, eventTime, eventType, eventInfo));
                }
            }
        }
    }
    return threadSnapshots;
}

