public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Check for null message and schema
    if (message == null || schema == null) {
        throw new NullPointerException("Message and schema cannot be null");
    }

    // Get the size of the message
    int size = schema.size(message);
    int sizeWithLength = size + VarInt.sizeOf(size);

    // Write the size and message to the output stream
    VarInt.write(sizeWithLength, out);
    schema.writeObject(out, message, buffer);

    // Flush the output stream
    out.flush();

    // Return the size of the message
    return sizeWithLength;
}

