public static int computeUTF8Size(CharSequence str, int index, int len) {
    // check for null input
    if (str == null) {
        throw new NullPointerException("str cannot be null");
    }

    // check for negative index or length
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("index and len must be non-negative");
    }

    // check for invalid index or length
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("index and len must be within the bounds of the input string");
    }

    // initialize result with the length of the input string
    int result = str.length();

    // iterate over the characters in the string
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);

        // handle two-byte characters
        if ((c & 0xE0) == 0xC0) {
            result++;
            i++;
        }
        // handle three-byte characters
        else if ((c & 0xF0) == 0xE0) {
            result += 2;
            i += 2;
        }
        // handle four-byte characters
        else if ((c & 0xF8) == 0xF0) {
            result += 3;
            i += 3;
        }
        // handle beyond-BMP characters
        else if ((c & 0xFC) == 0xF8) {
            result += 4;
            i += 4;
        }
    }

    // return the final result
    return result;
}

